pending = {}
def send_request(method, params):
    request_id = next_id()
    pending[request_id] = create_future()
    transport.send({"jsonrpc": "2.0", "id": request_id, "method": method, "params": params})
    return pending[request_id]

def on_response(resp):
    future = pending.pop(resp["id"])
    future.resolve(resp.get("result", resp.get("error")))

request = {"jsonrpc": "2.0", "id": 4, "method": "tools/call", "params": {"name": "get_weather", "arguments": {"city": "Mumbai"}}}

success_response = {"jsonrpc": "2.0", "id": 4, "result": {"temperature_c": 31}}
failure_response = {"jsonrpc": "2.0", "id": 4, "error": {"code": "service_unavailable", "message": "Weather service is down"}}

# handling either outcome generically
def handle(resp):
    if "error" in resp:
        return f"Failed: {resp['error']['message']}"
    return f"Success: {resp['result']}"

def handle_response(resp):
    if "error" in resp:
        raise RuntimeError(resp["error"]["message"])
    return resp["result"]
